import { SeoRoute } from '../models/catalog.model';
import routesJson from './seo-routes.json';

/** Routes with their own SEO page, most booked first (generated by scripts/build-catalog.py). */
export const SEO_ROUTES: readonly SeoRoute[] = routesJson as SeoRoute[];

export const SEO_ROUTE_BY_SLUG = new Map(SEO_ROUTES.map((r) => [r.slug, r]));

export function routePath(route: Pick<SeoRoute, 'slug'>): string {
  return `/taxi/${route.slug}`;
}

/** Routes starting or ending at a place (by fare-data key), most booked first. */
export function routesFor(placeKey: string, limit = 12): SeoRoute[] {
  return SEO_ROUTES.filter((r) => r.from === placeKey || r.to === placeKey).slice(0, limit);
}

export function reverseOf(route: SeoRoute): SeoRoute | undefined {
  return SEO_ROUTES.find((r) => r.from === route.to && r.to === route.from);
}

/** Other pages to link from a route page: the return trip first, then routes sharing a city. */
export function relatedRoutes(route: SeoRoute, limit = 8): SeoRoute[] {
  const reverse = reverseOf(route);
  const others = SEO_ROUTES.filter(
    (r) => r !== route && r !== reverse && (r.from === route.from || r.to === route.to || r.from === route.to),
  );
  return [...(reverse ? [reverse] : []), ...others].slice(0, limit);
}
